using System.Reflection;
using System.Text.Json;

namespace Jellyfin.Plugin.GenreMapper.Genres;

/// <summary>
/// The official genres of the metadata providers and their translations, bundled with the plugin as they rarely change.
/// </summary>
/// <remarks>
/// <c>Data/tmdb-genres.json</c> is generated by <c>scripts/update_tmdb_genres.py</c>, <c>Data/genres.json</c> is written by hand:
/// it lists the TheTVDB genres, links them to the TMDb genres, and gives better names than TMDb in some languages.
/// </remarks>
public static class KnownGenres
{
    private const string DefaultLanguage = "en";

    private static readonly Lazy<GenreData> _data = new(Load);

    /// <summary>
    /// Gets the official TheTVDB genres, only in English.
    /// </summary>
    public static IReadOnlyList<string> TvdbGenres => _data.Value.Tvdb;

    /// <summary>
    /// Gets the genre concepts: the names of a genre in every language, used to suggest merges.
    /// </summary>
    public static IReadOnlyList<GenreConcept> Concepts => _data.Value.Concepts;

    /// <summary>
    /// Gets the language of the TMDb genre lists used for a metadata language.
    /// </summary>
    /// <param name="metadataLanguage">The metadata language, like <c>fr</c> or <c>pt-BR</c>.</param>
    /// <returns>The language of the lists, English if the language is unknown.</returns>
    public static string ResolveLanguage(string? metadataLanguage)
    {
        IReadOnlyDictionary<string, IReadOnlyList<string>> tmdb = _data.Value.Tmdb;
        string code = (metadataLanguage ?? string.Empty).Trim();

        return tmdb.Keys.FirstOrDefault(key => string.Equals(key, code, StringComparison.OrdinalIgnoreCase))
            ?? tmdb.Keys.FirstOrDefault(key => string.Equals(key, code.Split('-')[0], StringComparison.OrdinalIgnoreCase))
            ?? DefaultLanguage;
    }

    /// <summary>
    /// Gets the official TMDb movie and TV genres in a language.
    /// </summary>
    /// <param name="language">A language returned by <see cref="ResolveLanguage"/>.</param>
    /// <returns>The genres.</returns>
    public static IReadOnlyList<string> GetTmdbGenres(string language) =>
        _data.Value.Tmdb.TryGetValue(language, out IReadOnlyList<string>? genres) ? genres : [];

    private static T Read<T>(string name)
    {
        Assembly assembly = typeof(KnownGenres).Assembly;
        using Stream stream = assembly.GetManifestResourceStream(typeof(Plugin).Namespace + ".Data." + name)
            ?? throw new InvalidOperationException("Missing embedded resource " + name);
        return JsonSerializer.Deserialize<T>(stream, new JsonSerializerOptions { PropertyNameCaseInsensitive = true })
            ?? throw new InvalidOperationException("Invalid embedded resource " + name);
    }

    private static GenreData Load()
    {
        TmdbFile tmdb = Read<TmdbFile>("tmdb-genres.json");
        GenresFile genres = Read<GenresFile>("genres.json");
        TmdbList[] lists = [tmdb.Movie, tmdb.Tv];
        string[] languages = lists.SelectMany(list => list.Languages.Keys).Distinct(StringComparer.Ordinal).ToArray();

        // Names of each TMDb genre in each language (the movie and TV names of a genre can differ)
        Dictionary<int, Dictionary<string, List<string>>> tmdbNames = [];
        foreach (TmdbList list in lists)
        {
            for (int index = 0; index < list.Ids.Length; index++)
            {
                Dictionary<string, List<string>> names = tmdbNames.TryGetValue(list.Ids[index], out var existing) ? existing : tmdbNames[list.Ids[index]] = [];
                foreach (string language in languages)
                {
                    string? name = GetName(list, language, index);
                    if (name is not null)
                    {
                        List<string> languageNames = names.TryGetValue(language, out var value) ? value : names[language] = [];
                        if (!languageNames.Contains(name, StringComparer.Ordinal))
                        {
                            languageNames.Add(name);
                        }
                    }
                }
            }
        }

        Dictionary<string, IReadOnlyList<string>> tmdbGenres = languages.ToDictionary(
            language => language,
            language => (IReadOnlyList<string>)tmdbNames.Values
                .SelectMany(names => names.TryGetValue(language, out var value) ? value : [])
                .Distinct(StringComparer.Ordinal)
                .ToArray(),
            StringComparer.Ordinal);

        // Concepts of the hand-written file first, then the TMDb genres it does not mention
        List<GenreConcept> concepts = [];
        HashSet<int> mentionedIds = [];
        foreach (ConceptEntry entry in genres.Concepts)
        {
            GenreConcept concept = new() { Tvdb = entry.Tvdb };
            if (entry.Tmdb is int id && tmdbNames.TryGetValue(id, out var names))
            {
                AddTmdbNames(concept, names);
                mentionedIds.Add(id);
            }

            if (entry.Tvdb is not null && !concept.Names.ContainsKey(DefaultLanguage))
            {
                AddName(concept, DefaultLanguage, entry.Tvdb, true);
            }

            foreach ((string language, string name) in entry.Names)
            {
                AddName(concept, language, name, true);
            }

            concepts.Add(concept);
        }

        foreach ((int id, Dictionary<string, List<string>> names) in tmdbNames.Where(pair => !mentionedIds.Contains(pair.Key)))
        {
            GenreConcept concept = new();
            AddTmdbNames(concept, names);
            concepts.Add(concept);
        }

        return new GenreData(genres.Tvdb, tmdbGenres, concepts);
    }

    // Untranslated names are null, Jellyfin then gets them from the base language or in English
    private static string? GetName(TmdbList list, string language, int index)
    {
        string[] candidates = [language, language.Split('-')[0], DefaultLanguage];
        return candidates
            .Select(candidate => list.Languages.TryGetValue(candidate, out string?[]? names) ? names[index] : null)
            .FirstOrDefault(name => name is not null);
    }

    private static void AddTmdbNames(GenreConcept concept, Dictionary<string, List<string>> names)
    {
        foreach ((string language, List<string> languageNames) in names)
        {
            foreach (string name in languageNames)
            {
                AddName(concept, language, name, false);
            }
        }
    }

    private static void AddName(GenreConcept concept, string language, string name, bool isPreferred)
    {
        List<string> aliases = concept.Aliases.TryGetValue(language, out var value) ? value : concept.Aliases[language] = [];
        if (!aliases.Contains(name, StringComparer.Ordinal))
        {
            aliases.Add(name);
        }

        if (isPreferred || !concept.Names.ContainsKey(language))
        {
            concept.Names[language] = name;
        }
    }

    private sealed record GenreData(IReadOnlyList<string> Tvdb, IReadOnlyDictionary<string, IReadOnlyList<string>> Tmdb, IReadOnlyList<GenreConcept> Concepts);

    private sealed class TmdbFile
    {
        public TmdbList Movie { get; set; } = new();

        public TmdbList Tv { get; set; } = new();
    }

    private sealed class TmdbList
    {
        public int[] Ids { get; set; } = [];

        // The names of the genres in each language, in the order of the ids
        public Dictionary<string, string?[]> Languages { get; set; } = [];
    }

    private sealed class GenresFile
    {
        public string[] Tvdb { get; set; } = [];

        public ConceptEntry[] Concepts { get; set; } = [];
    }

    private sealed class ConceptEntry
    {
        public int? Tmdb { get; set; }

        public string? Tvdb { get; set; }

        public Dictionary<string, string> Names { get; set; } = [];
    }
}
